<?php
require_once __DIR__.'/includes/db.php';
if(empty($_SESSION['user_id'])||($_SESSION['role']??'')!=='admin'){http_response_code(403);exit('Admin access only. Sign in with an account whose role is admin.');}
$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='add'){$name=trim($_POST['name']??'');$category=$_POST['category']??'Electronics';$price=(float)($_POST['price']??0);$image=trim($_POST['image']??'');$description=trim($_POST['description']??'');if($name!==''&&$price>0){$st=$pdo->prepare("INSERT INTO products(name,category,price,image,description) VALUES(?,?,?,?,?)");$st->execute([$name,$category,$price,$image,$description]);$msg='Product added.';}else $msg='Enter a product name and positive price.';}
 if($action==='status'){$id=(int)$_POST['id'];$status=$_POST['status']??'Pending';$allowed=['Pending','Processing','Shipped','Delivered','Cancelled'];if(in_array($status,$allowed,true)){$st=$pdo->prepare("UPDATE orders SET status=? WHERE id=?");$st->execute([$status,$id]);$msg='Order status updated.';}}
}
$products=$pdo->query("SELECT * FROM products ORDER BY id DESC")->fetchAll();$orders=$pdo->query("SELECT o.*,u.name AS customer FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin | GoldCart</title><link rel="stylesheet" href="assets/style.css"></head><body><header class="topbar"><a class="brand" href="index.php">GOLD<span>CART</span></a><nav><a href="index.php">Store</a><a href="logout.php">Logout</a></nav></header><main class="container"><p class="eyebrow">STORE MANAGEMENT</p><h1>Admin Panel</h1><?php if($msg): ?><div class="notice"><?= htmlspecialchars($msg) ?></div><?php endif; ?><div class="panel"><h2>Add Product</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= htmlspecialchars(csrf_token()) ?>"><input type="hidden" name="action" value="add"><label>Product Name<input name="name" required></label><label>Category<select name="category"><option>Electronics</option><option>Fashion</option><option>Home & Furniture</option><option>Accessories</option></select></label><label>Price in INR<input type="number" name="price" min="1" step=".01" required></label><label>Image URL or relative path<input name="image" placeholder="assets/placeholder.svg"></label><label>Description<textarea name="description" rows="2"></textarea></label><button class="btn">Add Product</button></form></div><div class="panel" style="margin-top:24px"><h2>Products</h2><div class="table-wrap"><table><tr><th>Name</th><th>Category</th><th>Price</th><th>Active</th></tr><?php foreach($products as $p): ?><tr><td><?= htmlspecialchars($p['name']) ?></td><td><?= htmlspecialchars($p['category']) ?></td><td>₹<?= number_format($p['price'],2) ?></td><td><?= $p['active']?'Yes':'No' ?></td></tr><?php endforeach; ?></table></div></div><div class="panel" style="margin-top:24px"><h2>Orders</h2><div class="table-wrap"><table><tr><th>Order</th><th>Customer</th><th>Total</th><th>Payment</th><th>Status</th><th>Update</th></tr><?php foreach($orders as $o): ?><tr><td><?= htmlspecialchars($o['order_no']) ?></td><td><?= htmlspecialchars($o['customer']) ?></td><td>₹<?= number_format($o['total'],2) ?></td><td><?= htmlspecialchars($o['payment_status']) ?></td><td><?= htmlspecialchars($o['status']) ?></td><td><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?= htmlspecialchars(csrf_token()) ?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?= (int)$o['id'] ?>"><select name="status"><?php foreach(['Pending','Processing','Shipped','Delivered','Cancelled'] as $s): ?><option <?= $o['status']===$s?'selected':'' ?>><?= $s ?></option><?php endforeach; ?></select><button class="btn small">Save</button></form></td></tr><?php endforeach; ?></table></div></div></main></body></html>
